    """Convert a value stored in a TensorData into a JSON-serializable object."""
    if isinstance(value, np.ndarray):
        return {"CLS": "numpy.array", "data": value.tolist(), "dtype": str(value.dtype)}
    if isinstance(value, np.generic):
